import type { EngineInterface, PluginOptions, Register, ToolCallResult } from 'claude-code'

import { PLAN_FILES, formatOutcomes, outcomeOf, parseCheckArgs, planChecks } from './check'
import type { CheckName, CheckOutcome } from './check'
import { LOCKFILES, THEME_PATH, exportingFiles, lines, parseProject, setsDefaultStaleTime } from './project'
import type { Project } from './project'
import {
  addedLines,
  analyzeEdit,
  duplicateFiles,
  expoInstallHint,
  exportedNames,
  findExplicitAny,
  findNonExpoInstalls,
  formatFindings,
  indexTheme,
  isAnalyzable,
} from './rules'
import type { Finding, ThemeIndex } from './rules'

type Policy = 'block' | 'warn'

type Settings = {
  anyPolicy: Policy
  installPolicy: Policy
  maxComponentLines: number
  maxIconsPerEdit: number
}

/** An edit judged before it runs: denied, or the facts to report on once it has. */
type EditPlan =
  | { deny: string }
  | { deny?: undefined; project: Project; path: string; absolute: string; before: string | undefined; after: string }

const NAME = 'react-native-code-guardian'
const CODE_GLOBS = ['*.ts', '*.tsx', '*.js', '*.jsx']
const GIT_TIMEOUT_MS = 10_000
const CHECK_TIMEOUT_MS = 5 * 60_000

// Caches for this load only; a reload starts them over.
let project: Promise<Project | undefined> | undefined
let theme: Promise<ThemeIndex> | undefined
let staleTimeDefault: Promise<boolean> | undefined

function readSettings(options: PluginOptions): Settings {
  const policy = (value: unknown): Policy => (value === 'warn' ? 'warn' : 'block')
  const count = (value: unknown, fallback: number): number =>
    typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback
  return {
    anyPolicy: policy(options.anyPolicy),
    installPolicy: policy(options.installPolicy),
    maxComponentLines: count(options.maxComponentLines, 250),
    maxIconsPerEdit: count(options.maxIconsPerEdit, 3),
  }
}

async function exists($: EngineInterface, path: string): Promise<boolean> {
  try {
    return await $.fs.exists(path)
  } catch {
    return false
  }
}

async function readText($: EngineInterface, path: string): Promise<string | undefined> {
  try {
    return (await $.fs.exists(path)) ? await $.fs.read(path) : undefined
  } catch {
    return undefined
  }
}

/** git's stdout for argv in the project, or undefined when git failed or is missing. */
async function git($: EngineInterface, root: string, argv: readonly string[]): Promise<string | undefined> {
  try {
    const ran = await $.process.run(['git', ...argv], { cwd: root, timeoutMs: GIT_TIMEOUT_MS })
    return ran.exitCode === 0 ? ran.stdout : undefined
  } catch {
    return undefined
  }
}

async function loadProject($: EngineInterface): Promise<Project | undefined> {
  const root = await $.session.cwd()
  const manifest = await readText($, `${root}/package.json`)
  if (manifest === undefined) return undefined
  let lockfile: string | undefined
  for (const [file] of LOCKFILES) if (lockfile === undefined && (await exists($, `${root}/${file}`))) lockfile = file
  return parseProject(root, manifest, lockfile)
}

function projectOf($: EngineInterface): Promise<Project | undefined> {
  project ??= loadProject($)
  return project
}

async function trackedFiles($: EngineInterface, root: string): Promise<string[]> {
  return lines((await git($, root, ['ls-files', '--cached', '--others', '--exclude-standard'])) ?? '')
}

async function loadTheme($: EngineInterface, root: string): Promise<ThemeIndex> {
  const index = new Map<string, string>()
  for (const file of (await trackedFiles($, root)).filter(path => THEME_PATH.test(path))) {
    const source = await readText($, `${root}/${file}`)
    for (const [color, token] of indexTheme(source ?? '')) if (!index.has(color)) index.set(color, token)
  }
  return index
}

function themeOf($: EngineInterface, root: string): Promise<ThemeIndex> {
  theme ??= loadTheme($, root)
  return theme
}

async function loadStaleTimeDefault($: EngineInterface, root: string): Promise<boolean> {
  const files = lines((await git($, root, ['grep', '-l', '-F', '--untracked', '-e', 'new QueryClient', '--', ...CODE_GLOBS])) ?? '')
  for (const file of files) if (setsDefaultStaleTime((await readText($, `${root}/${file}`)) ?? '')) return true
  return false
}

function staleTimeOf($: EngineInterface, root: string): Promise<boolean> {
  staleTimeDefault ??= loadStaleTimeDefault($, root)
  return staleTimeDefault
}

async function duplicatesOf($: EngineInterface, root: string, path: string, before: string | undefined, after: string): Promise<Finding[]> {
  const findings: Finding[] = []
  if (before === undefined) {
    const same = duplicateFiles(path, await trackedFiles($, root))
    if (same.length > 0)
      findings.push({ rule: 'duplicate-file', message: `A file named like ${path} already exists: ${same.slice(0, 3).join(', ')}. Reuse or extend it instead of adding a parallel implementation.` })
  }
  for (const name of exportedNames(addedLines(before, after))) {
    const rows = await git($, root, ['grep', '-I', '-F', '--untracked', '-e', name, '--', ...CODE_GLOBS])
    const others = exportingFiles(rows ?? '', name, path)
    if (others.length > 0)
      findings.push({ rule: 'duplicate-export', message: `\`${name}\` is already exported from ${others.slice(0, 3).join(', ')}. Reuse that implementation (or rename it if it is genuinely different).` })
  }
  return findings
}

/** Judges an Edit or Write before it runs; undefined when the file is not this mod's business. */
async function planEdit($: EngineInterface, settings: Settings, absolute: string, simulate: (before: string | undefined) => string): Promise<EditPlan | undefined> {
  const current = await projectOf($)
  if (current === undefined || !current.isReactNative || !absolute.startsWith(`${current.root}/`)) return undefined
  const path = absolute.slice(current.root.length + 1)
  if (!isAnalyzable(path)) return undefined
  const before = await readText($, absolute)
  const after = simulate(before)
  const anyLine = findExplicitAny(path, addedLines(before, after))[0]
  if (settings.anyPolicy === 'block' && anyLine !== undefined)
    return {
      deny: `${NAME}: this edit adds an explicit \`any\` to ${path} (${anyLine}). The project forbids \`any\` / \`as any\`. Use a precise type, a generic, or \`unknown\` narrowed by a type guard or a Zod schema, then retry.`,
    }
  return { project: current, path, absolute, before, after }
}

/** After an edit ran: the warnings for what it added, for the model (context) and the person (toast). */
async function reportEdit<T extends ToolCallResult>($: EngineInterface, settings: Settings, plan: EditPlan | undefined, ran: T): Promise<T> {
  if (plan === undefined || plan.deny !== undefined || ran.deny !== undefined || ran.isError === true) return ran
  const { project: current, path, before } = plan
  const after = (await readText($, plan.absolute)) ?? plan.after
  if (after.includes('QueryClient')) staleTimeDefault = undefined
  if (THEME_PATH.test(path)) theme = undefined
  const findings = [
    ...analyzeEdit({
      path,
      before,
      after,
      theme: await themeOf($, current.root),
      hasGlobalStaleTime: await staleTimeOf($, current.root),
      maxComponentLines: settings.maxComponentLines,
      maxIconsPerEdit: settings.maxIconsPerEdit,
    }),
    ...(await duplicatesOf($, current.root, path, before, after)),
  ]
  if (findings.length === 0) return ran
  const rules = [...new Set(findings.map(finding => finding.rule))].join(', ')
  $.ui.toast(`RN guardian: ${path}: ${rules}`, { timeoutMs: 6000 })
  return { ...ran, context: [...(ran.context ?? []), formatFindings(path, findings)] }
}

async function runChecks($: EngineInterface, current: Project, names: readonly CheckName[]): Promise<CheckOutcome[]> {
  const present = new Set<string>()
  for (const file of PLAN_FILES) if (await exists($, `${current.root}/${file}`)) present.add(file)
  const outcomes: CheckOutcome[] = []
  for (const plan of planChecks(current, present, names)) {
    if ('skip' in plan) {
      outcomes.push({ name: plan.name, status: 'skipped', reason: plan.skip })
      continue
    }
    $.ui.status(`/check: running ${plan.name} (${plan.argv.join(' ')})`)
    const started = await $.clock.now()
    try {
      const ran = await $.process.run(plan.argv, { cwd: current.root, env: plan.env, timeoutMs: CHECK_TIMEOUT_MS })
      outcomes.push(outcomeOf(plan, (await $.clock.now()) - started, ran))
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      outcomes.push(outcomeOf(plan, (await $.clock.now()) - started, { error: message }))
    }
  }
  $.ui.status(undefined)
  return outcomes
}

export const register: Register = (on, options) => {
  const settings = readSettings(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'check',
      description: "Run the project's TypeScript, lint and test checks (args: ts, lint, test)",
      argumentHint: '[ts] [lint] [test]',
    })
    return next(e)
  })

  on('command.run', { command: 'check' }, async ($, e) => {
    const current = await projectOf($)
    if (current === undefined) return { text: '/check: no package.json in the working directory; nothing was run.' }
    const names = parseCheckArgs(e.args)
    if (names === undefined) return { text: `/check: unknown check in "${e.args}". Use ts, lint or test.` }
    const report = formatOutcomes(await runChecks($, current, names))
    return { text: report, context: [report] }
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    if (e.tool !== 'Edit') return next(e)
    const { old_string, new_string, replace_all } = e
    const plan = await planEdit($, settings, e.file_path, before => {
      const text = before ?? ''
      return replace_all === true ? text.split(old_string).join(new_string) : text.replace(old_string, () => new_string)
    })
    if (plan?.deny !== undefined) return { deny: plan.deny }
    return reportEdit($, settings, plan, await next(e))
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    if (e.tool !== 'Write') return next(e)
    const { content } = e
    const plan = await planEdit($, settings, e.file_path, () => content)
    if (plan?.deny !== undefined) return { deny: plan.deny }
    return reportEdit($, settings, plan, await next(e))
  }).catch(($, e, next) => next(e))

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (e.tool !== 'Bash') return next(e)
    const current = await projectOf($)
    const installs = current?.isExpo === true ? findNonExpoInstalls(e.command) : []
    if (installs.length === 0) return next(e)
    const message = `${NAME}: this is an Expo project; add packages with \`${installs.map(expoInstallHint).join('; ')}\` so versions match the Expo SDK (instead of: ${installs.join('; ')}).`
    if (settings.installPolicy === 'block') return { deny: message }
    $.ui.toast('RN guardian: use npx expo install', { timeoutMs: 6000 })
    const ran = await next(e)
    return ran.deny === undefined ? { ...ran, context: [...(ran.context ?? []), message] } : ran
  }).catch(($, e, next) => next(e))
}

