// Pure planning and reporting for /check; register.ts runs the commands.

import type { PackageManager, Project } from './project'

export type CheckName = 'typescript' | 'lint' | 'tests'

export type CheckPlan =
  | { name: CheckName; argv: readonly string[]; env?: Record<string, string> }
  | { name: CheckName; skip: string }

export type CheckOutcome =
  | { name: CheckName; status: 'passed'; command: string; durationMs: number }
  | { name: CheckName; status: 'failed'; command: string; durationMs: number; output: string }
  | { name: CheckName; status: 'skipped'; reason: string }

/** Project files whose presence decides the plans, relative to the root. */
export const ESLINT_CONFIGS = [
  'eslint.config.js', 'eslint.config.mjs', 'eslint.config.cjs', 'eslint.config.ts',
  '.eslintrc', '.eslintrc.js', '.eslintrc.cjs', '.eslintrc.json', '.eslintrc.yml', '.eslintrc.yaml',
] as const
export const PLAN_FILES = ['tsconfig.json', 'node_modules/.bin/tsc', ...ESLINT_CONFIGS] as const

const TYPECHECK_SCRIPTS = ['typecheck', 'type-check', 'tsc', 'check:types', 'types']
const ALL: readonly CheckName[] = ['typescript', 'lint', 'tests']

const runScript = (manager: PackageManager, script: string): string[] => {
  if (manager === 'npm') return ['npm', 'run', '--silent', script]
  if (manager === 'yarn') return ['yarn', script]
  return [manager, 'run', script]
}

const planTypescript = (project: Project, present: ReadonlySet<string>): CheckPlan => {
  const script = TYPECHECK_SCRIPTS.find(name => name in project.scripts)
  if (script !== undefined) return { name: 'typescript', argv: runScript(project.packageManager, script) }
  if (!present.has('tsconfig.json')) return { name: 'typescript', skip: 'no tsconfig.json' }
  // The local binary only: `npx tsc` could download a package.
  if (!present.has('node_modules/.bin/tsc'))
    return { name: 'typescript', skip: 'typescript is not installed (node_modules/.bin/tsc missing); install dependencies first' }
  return { name: 'typescript', argv: ['node_modules/.bin/tsc', '--noEmit'] }
}

const planLint = (project: Project, present: ReadonlySet<string>): CheckPlan => {
  const script = project.scripts.lint
  if (script === undefined) return { name: 'lint', skip: 'no "lint" script in package.json' }
  // `expo lint` with no config installs and configures ESLint: network access and new files.
  if (/\bexpo\s+lint\b/.test(script) && !ESLINT_CONFIGS.some(file => present.has(file)))
    return { name: 'lint', skip: '`expo lint` has no ESLint config yet and would install and configure ESLint (network access, new files); run `npx expo lint` yourself once to set it up' }
  return { name: 'lint', argv: runScript(project.packageManager, 'lint') }
}

const planTests = (project: Project): CheckPlan => {
  const script = project.scripts.test
  if (script === undefined || /no test specified/.test(script)) return { name: 'tests', skip: 'no "test" script in package.json' }
  if (/--watch/.test(script)) return { name: 'tests', skip: 'the "test" script runs in watch mode and would not exit' }
  return { name: 'tests', argv: runScript(project.packageManager, 'test'), env: { CI: 'true' } }
}

export const planChecks = (project: Project, present: ReadonlySet<string>, names: readonly CheckName[]): CheckPlan[] =>
  names.map(name => {
    if (name === 'typescript') return planTypescript(project, present)
    if (name === 'lint') return planLint(project, present)
    return planTests(project)
  })

const ALIASES: Readonly<Record<string, CheckName>> = {
  ts: 'typescript', tsc: 'typescript', types: 'typescript', typescript: 'typescript', typecheck: 'typescript',
  lint: 'lint', eslint: 'lint',
  test: 'tests', tests: 'tests', jest: 'tests',
}

/** The checks `/check <args>` asks for: all when none named; undefined when a word names none. */
export const parseCheckArgs = (args: string): CheckName[] | undefined => {
  const words = args.toLowerCase().split(/[\s,]+/).filter(Boolean)
  if (words.length === 0) return [...ALL]
  const named = words.map(word => ALIASES[word])
  if (named.some(name => name === undefined)) return undefined
  return ALL.filter(name => named.includes(name))
}

const tail = (text: string, count: number): string => text.trimEnd().split('\n').slice(-count).join('\n')

export const outcomeOf = (
  plan: Extract<CheckPlan, { argv: readonly string[] }>,
  durationMs: number,
  ran: { exitCode: number; stdout: string; stderr: string } | { error: string },
): CheckOutcome => {
  const command = plan.argv.join(' ')
  if ('error' in ran) return { name: plan.name, status: 'failed', command, durationMs, output: `did not finish: ${ran.error}` }
  return ran.exitCode === 0
    ? { name: plan.name, status: 'passed', command, durationMs }
    : { name: plan.name, status: 'failed', command, durationMs, output: tail(`${ran.stdout}\n${ran.stderr}`, 40) || `exit code ${ran.exitCode}` }
}

export const formatOutcomes = (outcomes: readonly CheckOutcome[]): string => {
  const rows = outcomes.map(outcome => {
    if (outcome.status === 'skipped') return `${outcome.name}: SKIPPED (${outcome.reason})`
    return `${outcome.name}: ${outcome.status.toUpperCase()} in ${(outcome.durationMs / 1000).toFixed(1)}s (${outcome.command})`
  })
  const failures = outcomes.flatMap(outcome => (outcome.status === 'failed' ? [`\n${outcome.name} output:\n${outcome.output}`] : []))
  const counts = (['passed', 'failed', 'skipped'] as const).map(status => `${outcomes.filter(outcome => outcome.status === status).length} ${status}`)
  return [`/check: ${counts.join(', ')}`, ...rows, ...failures].join('\n')
}

