// Pure reading of the project's package.json and git output; register.ts does the I/O.

export type PackageManager = 'npm' | 'yarn' | 'pnpm' | 'bun'

export type Project = {
  root: string
  isReactNative: boolean
  isExpo: boolean
  scripts: Readonly<Record<string, string>>
  packageManager: PackageManager
}

export const LOCKFILES: readonly (readonly [string, PackageManager])[] = [
  ['bun.lock', 'bun'],
  ['bun.lockb', 'bun'],
  ['yarn.lock', 'yarn'],
  ['pnpm-lock.yaml', 'pnpm'],
]

export const THEME_PATH = /(^|\/)(theme|colors?|tokens?|palette)\.(ts|tsx|js)$/i

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

const stringRecord = (value: unknown): Record<string, string> =>
  isRecord(value)
    ? Object.fromEntries(Object.entries(value).filter((entry): entry is [string, string] => typeof entry[1] === 'string'))
    : {}

/** The project described by its package.json text; undefined when the text is not a manifest. */
export const parseProject = (root: string, manifestText: string, lockfile: string | undefined): Project | undefined => {
  let manifest: unknown
  try {
    manifest = JSON.parse(manifestText)
  } catch {
    return undefined
  }
  if (!isRecord(manifest)) return undefined
  const deps = { ...stringRecord(manifest.dependencies), ...stringRecord(manifest.devDependencies) }
  return {
    root,
    isReactNative: 'react-native' in deps || 'expo' in deps,
    isExpo: 'expo' in deps,
    scripts: stringRecord(manifest.scripts),
    packageManager: LOCKFILES.find(([file]) => file === lockfile)?.[1] ?? 'npm',
  }
}

export const lines = (stdout: string): string[] => stdout.split('\n').filter(Boolean)

/** Whether a QueryClient source sets a default staleTime. */
export const setsDefaultStaleTime = (source: string): boolean => /defaultOptions[\s\S]*staleTime\s*:/.test(source)

/** Files of `git grep -F <name>` rows (`file:text`) that declare an export of `name`, other than `exclude`. */
export const exportingFiles = (stdout: string, name: string, exclude: string): string[] => {
  const declares = new RegExp(String.raw`^\s*export\s+(default\s+)?(async\s+)?(function|const|let|class|interface|type|enum)\s+${name}\b`)
  const files = new Set<string>()
  for (const row of lines(stdout)) {
    const split = row.indexOf(':')
    const file = row.slice(0, split)
    if (split > 0 && file !== exclude && !file.startsWith('node_modules/') && declares.test(row.slice(split + 1))) files.add(file)
  }
  return [...files]
}

