// Pure detectors: no `$`, no I/O. Each one reads the lines an edit adds and
// answers findings; register.ts decides whether a finding blocks or warns.

export type RuleId =
  | 'any'
  | 'ts-suppress'
  | 'web-element'
  | 'browser-api'
  | 'router-convention'
  | 'direct-http'
  | 'effect-fetch'
  | 'query-stale-time'
  | 'query-key'
  | 'query-global-refetch'
  | 'store-server-data'
  | 'badge'
  | 'icons'
  | 'color'
  | 'component-size'
  | 'duplicate-file'
  | 'duplicate-export'

export type Finding = { rule: RuleId; message: string }

export type ThemeIndex = ReadonlyMap<string, string>

export type EditFacts = {
  /** Path relative to the project root, `/`-separated. */
  path: string
  /** File text before the edit; undefined when the file is new. */
  before: string | undefined
  after: string
  theme: ThemeIndex
  /** Whether a QueryClient in the project sets a default staleTime. */
  hasGlobalStaleTime: boolean
  maxComponentLines: number
  maxIconsPerEdit: number
}

const CODE_FILE = /\.(ts|tsx|js|jsx|mts|cts)$/
const TS_FILE = /\.(ts|tsx|mts|cts)$/
const JSX_FILE = /\.(tsx|jsx)$/
const WEB_ONLY_FILE = /(\.web\.(tsx|jsx|ts|js)|\/\+html\.(tsx|jsx))$/
const SERVICE_LAYER = /(^|\/)(services?|api|apis|clients?|lib\/(api|http))\//
const THEME_FILE = /(^|\/)(theme|colors?|tokens?|palette)(\.[a-z]+)?\.(ts|tsx|js)$/i
const APP_DIR = /^(src\/)?app\//
const IGNORED_DIR = /^(node_modules|\.expo|ios|android|dist|build|web-build)\//

export const isAnalyzable = (path: string): boolean =>
  CODE_FILE.test(path) && !IGNORED_DIR.test(path)

/** Lines of `after` that `before` did not hold (a multiset diff, whitespace-trimmed). */
export const addedLines = (before: string | undefined, after: string): string[] => {
  const left = new Map<string, number>()
  for (const line of (before ?? '').split('\n')) {
    const key = line.trim()
    left.set(key, (left.get(key) ?? 0) + 1)
  }
  const added: string[] = []
  for (const line of after.split('\n')) {
    const key = line.trim()
    const count = left.get(key) ?? 0
    if (count > 0) left.set(key, count - 1)
    else if (key !== '') added.push(line)
  }
  return added
}

const stripComments = (line: string): string => {
  const trimmed = line.trim()
  if (trimmed.startsWith('*') || trimmed.startsWith('/*')) return ''
  return line.replace(/(^|[^:])\/\/.*$/, '$1').replace(/\/\*.*?\*\//g, '')
}

const stripStrings = (line: string): string =>
  line.replace(/'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*"|`(?:[^`\\]|\\.)*`/g, '""')

/** Code with comments and string contents removed: what the type and JSX rules read. */
const codeOf = (lines: readonly string[]): string[] =>
  lines.map(line => stripStrings(stripComments(line)))

const ANY_PATTERNS = [/\bas\s+any\b/, /[:<,|&(=]\s*any\b(?!\s*[=:(.])/, /\bany\s*\[\s*\]/]

export const findExplicitAny = (path: string, added: readonly string[]): string[] =>
  TS_FILE.test(path)
    ? codeOf(added)
        .map((code, index) => ({ code, raw: added[index] ?? '' }))
        .filter(({ code }) => ANY_PATTERNS.some(pattern => pattern.test(code)))
        .map(({ raw }) => raw.trim())
    : []

/** A Bash command's package installs that bypass `npx expo install`. */
export const findNonExpoInstalls = (command: string): string[] => {
  const offending: string[] = []
  for (const segment of command.split(/&&|\|\||;|\||\n/)) {
    const words = segment.trim().split(/\s+/).filter(Boolean)
    const [tool, sub, ...rest] = words
    if (tool === undefined || sub === undefined) continue
    const packages = rest.filter(word => !word.startsWith('-'))
    const isGlobal = rest.some(word => word === '-g' || word === '--global')
    if (packages.length === 0 || isGlobal) continue
    const installs =
      (tool === 'npm' && ['install', 'i', 'add', 'isntall'].includes(sub)) ||
      (tool === 'yarn' && sub === 'add') ||
      (tool === 'pnpm' && ['add', 'install', 'i'].includes(sub)) ||
      (tool === 'bun' && ['add', 'install', 'i'].includes(sub))
    if (installs) offending.push(segment.trim())
  }
  return offending
}

export const expoInstallHint = (segment: string): string => {
  const words = segment.split(/\s+/).slice(2)
  const isDev = words.some(word => ['-D', '--save-dev', '--dev', '-d'].includes(word))
  const packages = words.filter(word => !word.startsWith('-'))
  return `npx expo install ${packages.join(' ')}${isDev ? ' -- --save-dev' : ''}`
}

const WEB_ELEMENT =
  /<(div|span|p|h[1-6]|button|input|textarea|select|option|img|a|ul|ol|li|section|header|footer|nav|main|article|aside|form|label|table|thead|tbody|tr|td|th|br|hr|iframe|video|audio|canvas|strong|em)(\s|>|\/)/
const BROWSER_API = /\b(document\.|window\.(location|addEventListener|innerWidth|innerHeight)|localStorage|sessionStorage)\b/
const HTTP_CALL = /\b(fetch\s*\(|axios(\.(get|post|put|patch|delete|request|head))?\s*\()/
const EFFECT = /\buseEffect\s*\(/
const ANY_HTTP = /\b(fetch\s*\(|axios\b|\bapi\.(get|post|put|patch|delete)\s*\()/
const QUERY_HOOK = /\buse(Suspense)?(Infinite)?Query\s*\(/
const UNSTABLE_KEY = /queryKey\s*:\s*\[[^\]]*\b(Date\.now|Math\.random|new Date)\b/
const GLOBAL_REFETCH = /\b(refetchOnMount|refetchOnWindowFocus|refetchOnReconnect)\s*:\s*false\b|\b(staleTime|gcTime)\s*:\s*Infinity\b/
const ZUSTAND_CREATE = /\bcreate\s*(<[^>]*>)?\s*\(\s*(\(|set\b)/
const BADGE = /<\w*(Badge|Chip|Pill|Tag)\b|^\s*\w*(badge|chip|pill)\w*\s*:\s*\{/i
const ICON =
  /<(Ionicons|MaterialIcons|MaterialCommunityIcons|Feather|FontAwesome\d?|AntDesign|Entypo|EvilIcons|Octicons|SimpleLineIcons|Foundation|Icon|IconSymbol|SymbolView|\w+Icon)\b/g
const HEX = /['"`](#[0-9a-fA-F]{3,8})['"`]/g
const COLOR_FN = /\b(rgba?|hsla?)\s*\(/
const NAMED_COLOR =
  /\b\w*[cC]olor\s*[:=]\s*['"](?!transparent|inherit|currentColor)([a-zA-Z]+)['"]/

const firstLine = (lines: readonly string[], pattern: RegExp): string | undefined =>
  lines.find(line => pattern.test(line))?.trim()

/** What every detector reads: the edit, its added lines, and the file's kind. */
type Scope = EditFacts & {
  added: string[]
  code: string[]
  withStrings: string[]
  isJsx: boolean
}

type Detector = (scope: Scope) => Finding[]

const found = (rule: RuleId, message: string | undefined): Finding[] =>
  message === undefined ? [] : [{ rule, message }]

const typeSafety: Detector = ({ path, added }) => {
  const anyLine = findExplicitAny(path, added)[0]
  const suppress = firstLine(added, /@ts-(ignore|nocheck)\b/)
  return [
    ...found('any', anyLine && `Explicit \`any\` added (${anyLine}). Use a precise type, a generic, or \`unknown\` narrowed by a type guard or a Zod schema.`),
    ...found('ts-suppress', suppress && `Type errors silenced (${suppress}). Fix the type instead of suppressing it.`),
  ]
}

const nativeOnly: Detector = ({ path, code, isJsx }) => {
  if (!isJsx || WEB_ONLY_FILE.test(path)) return []
  const element = code.map(line => WEB_ELEMENT.exec(line)?.[1]).find(name => name !== undefined)
  const api = firstLine(code, BROWSER_API)
  return [
    ...found('web-element', element && `Web-only <${element}> in a native file. Use React Native primitives (View, Text, Pressable, Image from expo-image) or the project's themed components; put web-only code in a .web.tsx file.`),
    ...found('browser-api', api && `Browser-only API in native code (${api}). Use the Expo/React Native equivalent or a .web.tsx file.`),
  ]
}

const NON_ROUTE_DIR = /(^|\/)(components|hooks|utils|lib|services|api|store|stores|schemas|types|constants)\//

const routerConvention: Detector = ({ path, before, after, isJsx }) => {
  if (!APP_DIR.test(path) || before !== undefined) return []
  const name = path.split('/').pop() ?? ''
  const isPlainTs = name.endsWith('.ts') && !name.endsWith('+api.ts')
  if (NON_ROUTE_DIR.test(path) || /^use[A-Z-]/.test(name) || isPlainTs)
    return found('router-convention', `${path} is not a screen, but every file under app/ becomes a route in Expo Router. Move it to src/components, src/hooks, src/services, etc.`)
  if (isJsx && !/export\s+default\b/.test(after))
    return found('router-convention', `${path} is a route without a default export; Expo Router needs \`export default\` for the screen.`)
  return []
}

const serverState: Detector = ({ path, after, code, withStrings, hasGlobalStaleTime }) => {
  const call = SERVICE_LAYER.test(path) ? undefined : firstLine(code, HTTP_CALL)
  const fetchesInEffect = code.some(line => EFFECT.test(line)) && code.some(line => ANY_HTTP.test(line))
  const lacksStaleTime = code.some(line => QUERY_HOOK.test(line)) && !hasGlobalStaleTime && !/\bstaleTime\s*:/.test(after)
  const key = firstLine(withStrings, UNSTABLE_KEY)
  const global = /new QueryClient|defaultOptions/.test(after) ? firstLine(code, GLOBAL_REFETCH) : undefined
  const storesServerData = /from\s+['"]zustand['"]/.test(after) && ZUSTAND_CREATE.test(after) && code.some(line => ANY_HTTP.test(line))
  return [
    ...found('direct-http', call && `Direct HTTP call outside the service layer (${call}). Put the request in a service (e.g. src/services) on the shared Axios instance and read it through a useQuery/useMutation hook.`),
    ...found('effect-fetch', fetchesInEffect ? 'Data fetched inside useEffect bypasses TanStack Query (no cache, refetches on every mount). Use useQuery with a stable key instead.' : undefined),
    ...found('query-stale-time', lacksStaleTime ? 'useQuery without a staleTime, and the QueryClient sets no default: the data counts as stale at once and refetches on every mount. Set a staleTime that fits how often this resource changes.' : undefined),
    ...found('query-key', key && `Unstable query key (${key}): a new key each render means a new cache entry and a refetch every time. Build keys from stable inputs, ideally a shared key factory.`),
    ...found('query-global-refetch', global && `Global refetch/cache default changed (${global}). This affects every query; confirm it is deliberate and prefer per-query options.`),
    ...found('store-server-data', storesServerData ? 'API data fetched into a Zustand store. Keep server state in TanStack Query; use Zustand only for client state.' : undefined),
  ]
}

const uiRules: Detector = ({ path, before, after, code, isJsx, maxIconsPerEdit, maxComponentLines }) => {
  if (!isJsx) return []
  const badge = firstLine(code, BADGE)
  const icons = code.flatMap(line => [...line.matchAll(ICON)].map(match => match[1]))
  const lines = after.split('\n').length
  const linesBefore = before?.split('\n').length ?? 0
  const isOversized = lines > maxComponentLines && lines > linesBefore
  return [
    ...found('badge', badge && `Badge/chip/tag added (${badge}). Project rule: no badges, chips or decorative tags above section headings; use a plain section title.`),
    ...found('icons', icons.length > maxIconsPerEdit ? `${icons.length} icons added in one edit (${[...new Set(icons)].join(', ')}). Use icons only where they carry meaning.` : undefined),
    ...found('component-size', isOversized ? `${path} is now ${lines} lines (limit ${maxComponentLines}). Split it into smaller components or move logic into hooks.` : undefined),
  ]
}

const colorsIn = (line: string): string[] => {
  const named = NAMED_COLOR.exec(line)?.[1]
  return [
    ...[...line.matchAll(HEX)].flatMap(match => (match[1] === undefined ? [] : [match[1]])),
    ...(COLOR_FN.test(line) ? [line.trim()] : []),
    ...(named === undefined ? [] : [named]),
  ]
}

const themeColors: Detector = ({ path, withStrings, theme }) => {
  if (THEME_FILE.test(path)) return []
  const colors = [...new Set(withStrings.flatMap(colorsIn))]
  if (colors.length === 0) return []
  const described = colors.slice(0, 5).map(color => {
    const token = theme.get(color.toLowerCase())
    return token === undefined ? `${color} (not in the theme)` : `${color} (use ${token})`
  })
  return found('color', `Hard-coded color${colors.length > 1 ? 's' : ''}: ${described.join(', ')}. Use the theme tokens (useTheme / Colors in constants/theme); do not add colors outside the palette.`)
}

const DETECTORS: readonly Detector[] = [typeSafety, nativeOnly, routerConvention, serverState, uiRules, themeColors]

export const analyzeEdit = (facts: EditFacts): Finding[] => {
  if (!isAnalyzable(facts.path)) return []
  const added = addedLines(facts.before, facts.after)
  if (added.length === 0) return []
  const scope: Scope = {
    ...facts,
    added,
    code: codeOf(added),
    withStrings: added.map(stripComments),
    isJsx: JSX_FILE.test(facts.path),
  }
  return DETECTORS.flatMap(detect => detect(scope))
}

/** Names a set of added lines exports: candidates for the duplicate-export check. */
export const exportedNames = (added: readonly string[]): string[] => {
  const names = new Set<string>()
  for (const line of codeOf(added)) {
    const match = /^\s*export\s+(?:default\s+)?(?:async\s+)?(?:function|const|let|class|interface|type|enum)\s+([A-Za-z_$][\w$]*)/.exec(line)
    if (match?.[1] !== undefined && match[1].length > 2) names.add(match[1])
  }
  return [...names].slice(0, 10)
}

/** A file's name with its extension and platform suffix removed (`button.web.tsx` -> `button`). */
export const baseName = (path: string): string =>
  (path.split('/').pop() ?? '').replace(/\.(ios|android|native|web)?\.?(tsx|ts|jsx|js)$/, '').replace(/\.$/, '')

const GENERIC_NAMES = new Set(['index', '_layout', 'types', 'constants', 'styles', 'utils', '+html', '+not-found'])

export const duplicateFiles = (path: string, tracked: readonly string[]): string[] => {
  const name = baseName(path)
  if (GENERIC_NAMES.has(name) || name.startsWith('[')) return []
  return tracked.filter(other => other !== path && isAnalyzable(other) && baseName(other) === name)
}

/** Maps each lower-cased hex color in a theme file to the token path that holds it. */
export const indexTheme = (source: string): Map<string, string> => {
  const index = new Map<string, string>()
  const stack: string[] = []
  for (const line of source.split('\n')) {
    const open = /^\s*(?:export\s+const\s+)?([A-Za-z_$][\w$]*)\s*[:=]\s*\{\s*$/.exec(line)
    if (open?.[1] !== undefined) {
      stack.push(open[1])
      continue
    }
    const value = /^\s*([A-Za-z_$][\w$]*)\s*:\s*['"](#[0-9a-fA-F]{3,8})['"]/.exec(line)
    if (value?.[1] !== undefined && value[2] !== undefined) {
      const key = value[2].toLowerCase()
      if (!index.has(key)) index.set(key, [...stack, value[1]].join('.'))
    }
    if (/^\s*\}/.test(line)) stack.pop()
  }
  return index
}

export const formatFindings = (path: string, findings: readonly Finding[]): string =>
  [
    `react-native-code-guardian found ${findings.length} rule issue${findings.length > 1 ? 's' : ''} in ${path}. Fix them where they apply, and tell the user about any you leave on purpose:`,
    ...findings.map(finding => `- [${finding.rule}] ${finding.message}`),
  ].join('\n')

